# Plan éditorial 17/11/2026 -> 01/01/2027 (créé le 08/11/2026, tout en brouillon à valider)
S="photos_selection/"
IGEND="Devis gratuit : écrivez-nous en message privé."
LIEND="Devis gratuit sur finitionsflorentin.fr"
def ph(f,kick,title,sub="Réalisé par Finitions Florentin.",theme="blanc",pos="50% 50%",foot="Un projet de rénovation ?"):
    return {"kind":"photo","photo":S+f,"kick":kick,"title":title,"sub":sub,"theme":theme,"pos":pos,"foot":foot}
D=[]
def day(date,card,ig,li,alt,tags_ig,tags_li):
    D.append(dict(date=date,card=card,ig=ig+"\n"+IGEND+"\n"+tags_ig,li=li+"\n\n"+LIEND+"\n\n"+tags_li,alt=alt))

