def perso_plan():
    import datetime as dt
    days=[d['date'] for d in D]; keys=sorted(PERSO_SUJET); fixed={"2026-12-30":12,"2026-12-31":13}
    pool=[i for i in range(len(PERSO_PERSO)) if i not in fixed.values()]; out=[]
    for d in days:
        wd=dt.date.fromisoformat(d).weekday()
        if d=="2026-12-24": out.append((d,PERSO_FETES,None)); continue
        if d=="2027-01-01": out.append((d,PERSO_AN,None)); continue
        if d in fixed: out.append((d,PERSO_PERSO[fixed[d]],None)); continue
        if wd in (2,6) or not keys:
            out.append((d,PERSO_PERSO[pool.pop(0)],None)); continue
        k=keys[0]
        if k==d: k=keys[1]
        keys.remove(k); out.append((d,PERSO_SUJET[k],k))
    return out,keys,pool
